budget { tokens: 12000  calls: 20 }

tool SupportInbox {
    use: http
    base_url: env.SUPPORT_INBOX_URL
    auth_header: "Authorization"
    auth_value: env.SUPPORT_INBOX_TOKEN
    allow_paths: "/v1/complaints/new"
    methods: "GET"
}

tool SupportEmail {
    use: email
    host: env.SUPPORT_SMTP_HOST
    username: env.SUPPORT_SMTP_USERNAME
    password: env.SUPPORT_SMTP_PASSWORD
    from: env.SUPPORT_EMAIL_FROM
    to: env.SUPPORT_EMAIL_TO
    tls: true
}

intentclassifier Urgency {
    model: "gpt-6-luna"
    choose kind: urgent | non_urgent | unsure
    confidence at least 0.8 else unsure
    guard { pii: mask }
}

intentclassifier ManagerDecision {
    model: "gpt-6-luna"
    choose kind: approve | reject | unclear
    confidence at least 0.8 else unsure
    guard { pii: mask }
}

agent ApologyDrafter {
    model: "gpt-6-luna"
    prompt: "apology-drafter"
    temperature: 0.2
    guard { pii: mask }
    output_schema: { apology: string }
}

workflow Main(complaint_body) {
    intentclassify Urgency on complaint_body -> urgency_record
        retry 1 backoff 2s timeout 30s
        on_failure {
            human_prompt "Urgency could not be classified. Please review and hold this complaint; no email will be sent." -> review_ack
            return { status: "held_for_review", detail: "Urgency classification failed.", reviewer_response: review_ack }
        }

    alt (urgency_record.kind == "unsure") {
        human_prompt "Urgency is unclear. Please review and hold this complaint; no email will be sent." -> review_ack
        return { status: "held_for_review", detail: "Urgency was unclear.", reviewer_response: review_ack }
    } else {
        alt (urgency_record.kind == "non_urgent") {
            delegate "Write a concise, empathetic apology for this complaint. Use only necessary details. Do not promise remedies or claim actions that are not supported.\nComplaint:\n{complaint_body}" to ApologyDrafter -> draft_record expecting { apology: string }
                retry 1 backoff 2s timeout 45s
                on_failure {
                    human_prompt "The apology draft could not be prepared. Please review and hold this complaint; no email will be sent." -> review_ack
                    return { status: "held_for_review", detail: "Drafting failed.", reviewer_response: review_ack }
                }

            human_prompt "A non-urgent apology draft is ready for your review. Do not send it automatically.\n\nDraft:\n{draft_record.apology}\n\nPlease review and hold or handle it under support policy." -> review_ack
            return { status: "draft_for_review", apology: draft_record.apology, reviewer_response: review_ack }
        } else {
            delegate "Write a concise, empathetic apology for this complaint. Use only necessary details. Do not promise remedies or claim actions that are not supported.\nComplaint:\n{complaint_body}" to ApologyDrafter -> draft_record expecting { apology: string }
                retry 1 backoff 2s timeout 45s
                on_failure {
                    human_prompt "The apology draft could not be prepared. Please review and hold this complaint; no email will be sent." -> review_ack
                    return { status: "held_for_review", detail: "Drafting failed.", reviewer_response: review_ack }
                }

            human_prompt "An urgent complaint has an apology draft ready. As manager, explicitly confirm or reject sending this specific draft. No email will be sent without the required approval.\n\nDraft:\n{draft_record.apology}\n\nReply approve, reject, or explain if unclear." -> manager_reply_text

            intentclassify ManagerDecision on manager_reply_text -> manager_choice
                retry 1 backoff 2s timeout 30s
                on_failure {
                    human_prompt "The manager's response could not be interpreted. Please review and hold this complaint; no email will be sent." -> review_ack
                    return { status: "held_for_review", detail: "Manager response was unclear.", reviewer_response: review_ack }
                }

            alt (manager_choice.kind == "approve") {
                human_prompt "The manager confirmed this urgent apology. A support reviewer must still approve the specific email before any send. Please review and hold or handle it under support policy.\n\nDraft:\n{draft_record.apology}" -> review_ack
                return { status: "approved_draft_for_review", apology: draft_record.apology, reviewer_response: review_ack }
            } else {
                human_prompt "The manager rejected or did not clearly approve sending. Please review and hold this complaint; no email will be sent.\n\nDraft:\n{draft_record.apology}" -> review_ack
                return { status: "held_for_review", detail: "Manager did not explicitly approve sending.", reviewer_response: review_ack }
            }
        }
    }
}
